def ensure_tasks_stage(apps, schema_editor):
    Stage = apps.get_model('recruitmentapp', 'RecruitmentStage')
    interview = Stage.objects.filter(code='interview', is_active=True).first()
    reference = Stage.objects.filter(code='reference-check', is_active=True).first()
    if reference:
        target_order = reference.order
    elif interview:
        target_order = interview.order + 1
    else:
        target_order = 4

    task = Stage.objects.filter(code='tasks').first()
    affected = list(Stage.objects.filter(is_active=True, order__gte=target_order).exclude(code='tasks').order_by('-order'))
    # Move rows out of the unique order range first, then make room for Tasks.
    for stage in affected:
        Stage.objects.filter(pk=stage.pk).update(order=stage.order + 1000)
    for stage in affected:
        Stage.objects.filter(pk=stage.pk).update(order=stage.order + 1)

    if task:
        Stage.objects.filter(pk=task.pk).update(
            name='Tasks', order=target_order, is_active=True, is_terminal=False, terminal_outcome='OPEN',
        )
    else:
        Stage.objects.create(
            code='tasks', name='Tasks', order=target_order, is_active=True,
            is_terminal=False, terminal_outcome='OPEN',
        )


